package com.paicli.state;

import java.nio.charset.StandardCharsets;import java.sql.*;import java.util.*;

public final class McpToolStore {
 public static final int MAX_SCHEMA_BYTES=2*1024*1024; private final Connection c; public McpToolStore(Connection c){this.c=c;}
 void insert(ToolRecord t)throws SQLException{validate(t);try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM mcp_tool_catalogs WHERE catalog_id=? AND server_id=? AND status='BUILDING'")){check.setString(1,t.catalogId());check.setString(2,t.serverId());try(ResultSet r=check.executeQuery()){if(!r.next())throw new IllegalArgumentException("tool does not match a building catalog/server");}}try(PreparedStatement s=c.prepareStatement("INSERT INTO mcp_tools(mcp_tool_id,catalog_id,server_id,original_name,exposed_name,bounded_title,bounded_description,normalized_input_schema_json,schema_hash,exposure_status,rejection_category) VALUES(?,?,?,?,?,?,?,?,?,?,?)")){int i=1;s.setString(i++,t.toolId());s.setString(i++,t.catalogId());s.setString(i++,t.serverId());s.setString(i++,t.originalName());s.setString(i++,t.exposedName());s.setString(i++,McpStoreSupport.optional(t.title(),256));s.setString(i++,McpStoreSupport.optional(t.description(),2048));s.setString(i++,t.schemaJson());s.setString(i++,McpStoreSupport.hash(t.schemaHash(),"schemaHash"));s.setString(i++,t.exposureStatus());s.setString(i,t.rejectionCategory());s.executeUpdate();}}
 private void validate(ToolRecord t){McpStoreSupport.id(t.toolId(),"toolId");if(!t.exposedName().equals(com.paicli.mcp.tool.McpToolNames.alias(t.serverId(),t.originalName()))&&!t.exposedName().equals("mcp."+t.serverId()+"."+t.originalName()))throw new IllegalArgumentException("unstable MCP exposed name");if(t.schemaJson()==null||t.schemaJson().getBytes(StandardCharsets.UTF_8).length>MAX_SCHEMA_BYTES)throw new IllegalArgumentException("schema outside bounds");if(!Set.of("EXPOSED","REJECTED").contains(t.exposureStatus()))throw new IllegalArgumentException("invalid exposure status");}
 public List<ToolRecord> findExposedToolsByCatalog(String id)throws SQLException{return list("catalog_id=? AND exposure_status='EXPOSED'",id);}
 public int countByExposure(String catalog,String exposure)throws SQLException{if(!Set.of("EXPOSED","REJECTED").contains(exposure))throw new IllegalArgumentException("invalid exposure");try(PreparedStatement s=c.prepareStatement("SELECT count(*) FROM mcp_tools WHERE catalog_id=? AND exposure_status=?")){s.setString(1,catalog);s.setString(2,exposure);try(ResultSet r=s.executeQuery()){return r.next()?r.getInt(1):0;}}}
 public Optional<ToolRecord> findByExposedName(String catalog,String name)throws SQLException{return one("catalog_id=? AND exposed_name=?",catalog,name);}
 public Optional<ToolRecord> findByOriginalName(String catalog,String name)throws SQLException{return one("catalog_id=? AND original_name=?",catalog,name);}
 public List<ToolRecord> findAll(String catalog)throws SQLException{return list("catalog_id=?",catalog);}
 public List<ReportToolRecord> findReportTools(String catalog,int limit)throws SQLException{if(limit<1)throw new IllegalArgumentException("limit >= 1");try(PreparedStatement s=c.prepareStatement("SELECT original_name,exposed_name,bounded_description,schema_hash,exposure_status,rejection_category FROM mcp_tools WHERE catalog_id=? ORDER BY original_name,mcp_tool_id LIMIT ?")){s.setString(1,catalog);s.setInt(2,limit);List<ReportToolRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(new ReportToolRecord(r.getString("original_name"),r.getString("exposed_name"),r.getString("bounded_description"),r.getString("schema_hash"),r.getString("exposure_status"),r.getString("rejection_category")));}return x;}}
 public List<ToolRecord> findAllLimited(String catalog,int limit)throws SQLException{if(limit<1)throw new IllegalArgumentException("limit >= 1");try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tools WHERE catalog_id=? ORDER BY original_name,mcp_tool_id LIMIT ?")){s.setString(1,catalog);s.setInt(2,limit);List<ToolRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private Optional<ToolRecord> one(String where,String...p)throws SQLException{List<ToolRecord>x=list(where,p);return x.stream().findFirst();}
 private List<ToolRecord> list(String where,String...p)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_tools WHERE "+where+" ORDER BY original_name")){for(int i=0;i<p.length;i++)s.setString(i+1,p[i]);List<ToolRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private ToolRecord map(ResultSet r)throws SQLException{return new ToolRecord(r.getString("mcp_tool_id"),r.getString("catalog_id"),r.getString("server_id"),r.getString("original_name"),r.getString("exposed_name"),r.getString("bounded_title"),r.getString("bounded_description"),r.getString("normalized_input_schema_json"),r.getString("schema_hash"),r.getString("exposure_status"),r.getString("rejection_category"));}
 public record ReportToolRecord(String originalName,String exposedName,String description,String schemaHash,String exposureStatus,String rejectionCategory){}
 public record ToolRecord(String toolId,String catalogId,String serverId,String originalName,String exposedName,String title,String description,String schemaJson,String schemaHash,String exposureStatus,String rejectionCategory){}
}
